export async function runCli(options: RunCliOptions = {}): Promise<void> {
  const version = getDshRuntimeVersion()
  const { manageDesktopProfile, ...profileOptions } = options
  const invocation = parseDshArgs(process.argv.slice(2), version, manageDesktopProfile)

  switch (invocation.mode) {
    case 'profile': {
      const { runProfile } = await import('./profile-boot.ts')
      try {
        await runProfile({
          environment: loadLayeredEnv('dsh'),
          profile: invocation.profile,
          fromDefaultProfile: invocation.fromDefaultProfile,
          patchFiles: invocation.patches,
          args: invocation.args,
          ...profileOptions,
        })
      } catch (error) {
        if (!(error instanceof StartupError)) throw error
        await reportStartupFailure(error, { home: resolveDshHome(), version, profile: invocation.profile })
        process.exit(1)
      }
      break

const composed = await composeProfile(
  options.profile, options.patchFiles, options.fromDefaultProfile, options.resolvedProfile,
)
const appReady = createAppReady()
const shutdown = createProcessShutdown(dispose)
const signalShutdown = new AbortController()
const interrupt = (code: number): void => {
  signalShutdown.abort()
  shutdown.interrupt(code)
}
// Signals own teardown throughout the startup window, not only after boot()
// settles: an inserted provider can publish before sibling rows finish mounting.
// SIGTERM is a supervisor's ordinary stop request and exits 0 on every
// surface — the launcher does not know whether the app considered its work
// complete; SIGINT is a user interrupt and reports 130.
process.on('SIGTERM', () => { interrupt(0) })
process.on('SIGINT', () => { interrupt(130) })
installFailLoud(NAME, process, async () => {
  await app.current?.fiber.dispose()
})

const rootConfig = join(composed.profile.dir, PROFILE_ROOT_FILENAME)
const profileContext: ProfileContext = {
  name: options.profile,
  ...(options.packageManager === undefined ? {} : { packageManager: options.packageManager }),
  dir: composed.profile.dir, patchPath: composed.profile.patchPath,
  installAnchor: options.resolvedProfile?.installAnchor ?? INSTALL_ANCHOR,
  startedBundles: composed.profile.layers.map(layer => layer.packageName),
  cwd: process.cwd(), home: resolveDshHome(),
  overlays: composed.overlays, telemetryDisabledEnv: process.env.DSH_TELEMETRY_DISABLED,
}
const ctx = await boot(NAME, rootConfig, readProfilePatches(NAME, profileContext, composed.profile), async (hostCtx) => {
  app.current = hostCtx
  hostCtx.provide('profileContext', profileContext)
  // Before any config-tree entry mounts, so plugins resolve all launch-time
  // environment values from the same immutable launch snapshot.
  hostCtx.provide(DSH_LAUNCH_ENVIRONMENT_KEY, options.environment)
  await hostCtx.plugin(PluginPackages, {
    resolution: composed.resolution,
  })
  // The command line and bounded exit request are launcher facts available
  // to every app plugin that injects the argument snapshot.
  provideCmdline(hostCtx, {
    args: options.args,
    exit: code => void shutdown.shutdown(code),
    ready: appReady.service,
  })
})
app.current = ctx
if (!signalShutdown.signal.aborted
  && ctx.fiber.state === FiberState.ACTIVE
  && ctx.get('loader') !== undefined) {
  appReady.commit()
}
return { ctx, shutdown }

export async function boot(
  binName: string,
  absoluteConfigPath: string,
  patches?: PatchOptions[],
  prepare?: (ctx: Context) => Promise<void> | void,
  bareModuleBaseUrl?: string,
): Promise<Context> {
  const ctx = new Context()
  const startupLogs: StartupLogRecord[] = []
  // The collector must outlive root disposal to retain asynchronous cleanup errors.
  const diagnostics = new Context()
  diagnostics.logger = ctx.logger
  diagnostics.logger.exporter({
    levels: { default: 2 },
    export: ({ ts, name, type, args }) => {
      if (type === 'warn' || type === 'error') startupLogs.push({ ts, name, type, args })
    },
  })
  // Two failure labels: `prepare` runs before any config-tree entry mounts,
  // so its failure is host setup, not the plugin tree.
  let stage = 'host preparation failed'
  try {
    ctx.baseUrl = pathToFileURL(dirname(absoluteConfigPath)).href + '/'
    ctx.provide('dshHomePath', dshHomePath)
    await ctx.plugin(Loader)
    await prepare?.(ctx)
    stage = 'plugin tree failed to load'
    await mountRootInclude(ctx, absoluteConfigPath, patches, bareModuleBaseUrl, binName)
    // A surface can finish and dispose the whole tree while startup is still
    // in flight, before the last entry settles. The Loader service goes with
    // it, and the activation audit describes a live tree — reading `ctx.loader`
    // past this point would throw a TypeError over an app that exited exactly
    // as asked. Re-check after settlement before auditing the tree.
    await ctx.get('loader')?.await()
    if (ctx.get('loader') === undefined) return ctx
    await auditStartupEntries(ctx, binName)
    return ctx

send(message: UserMessage, target: InboxTarget, wakeup: boolean): void {
  // Waking input cannot join an aborted activity, so it starts the next turn.
  // Captured before the insertion so a reentrant cancel from a splice observer cannot reclassify it.
  const wakingAfterAbort = wakeup && this.phase.kind !== 'idle' && this.phase.abort.signal.aborted
  const resolvedTarget = wakingAfterAbort ? 'next-turn' : target
  this.inbox.splice(resolvedTarget, Infinity, 0, [message])
  if (wakeup) this.wakeDriver(wakingAfterAbort)
}

followup(input: UserMessage): void {
  this.send(input, 'next-turn', true)
}

steer(input: UserMessage): void {
  this.send(input, 'next-step', true)
}

inject(input: UserMessage): void {
  this.send(input, 'next-step', false)
}

cancel(cause: AgentCancelCause, options: CancelOptions = {}): void {
  if (!options.keepInbox) {
    this.inbox.clear()
    if (this.phase.kind !== 'idle') this.phase.wakeRequested = false
  }
  if (this.phase.kind !== 'idle') this.phase.abort.abort(cause)
}

private wakeDriver(wakeAfterAbort = false): void {
  if (this.phase.kind !== 'idle') {
    // Maintenance and aborted drivers cannot deliver the wake: latch it for
    // replay at convergence. Live drivers claim queued work themselves;
    // disposal never latches, so teardown waits on no model turn.
    const reason = abortedCancelCause(this.phase.abort.signal)
    if (reason?.kind !== 'disposed' && (this.phase.kind === 'maintenance' || wakeAfterAbort)) {
      this.phase.wakeRequested = true
    }
    return
  }
  const driver = Promise.withResolvers<void>()
  this.activityDone = driver.promise
  this.setPhase({
    kind: 'running',
    abort: new AbortController(),
    turn: this.phase.lastTurn,
    step: 0,
    wakeRequested: false,
  })
  this.loopCtx.agents.withInitiator(this, () => this.kick()).then(driver.resolve, driver.reject)
}

async whenIdle(): Promise<void> {
  let activity: Promise<void>
  do {
    await (activity = this.activityDone)
  } while (activity !== this.activityDone)
}

/** Report one failure at its live boundary, then preserve it for driver containment. */
private throwError(error: unknown): never {
  const turn = this.phase.kind === 'running' ? this.phase.turn : this.phase.lastTurn
  const step = this.phase.kind === 'running' ? this.phase.step : 0
  this.dispatch.emit('agent/error', { turn, step, error })
  throw error
}

private async kick(): Promise<void> {
  try {
    while (await this.turn()) {}
  } catch (_error) {
    // Reported failures and cancellation are contained at the driver boundary.
  } finally {
    /* v8 ignore next -- kick owns a running phase until this driver boundary */
    if (this.phase.kind === 'running') {
      const { turn, wakeRequested } = this.phase
      this.setPhase({ kind: 'idle', lastTurn: turn })
      if (wakeRequested && this.inbox.hasPending) this.wakeDriver()
    }
  }
}

/** Open one turn before claiming its first proposed step. */
private async turn(): Promise<boolean> {
  if (this.phase.kind !== 'running') {
    this.throwError(new Error(`agent "${this.id}": turn without driver reservation`))
  }
  const phase = this.phase
  const { signal } = phase.abort
  signal.throwIfAborted()
  const turn = phase.turn + 1
  try {
    this.session.append('turn/start', { turn })
  } catch (error: unknown) {
    this.throwError(error)
  }
  phase.turn = turn
  let turnEnds: TurnEndReason | null = null
  let target: InboxTarget = 'next-turn'
  try {
    while (true) {
      signal.throwIfAborted()
      const step = phase.step + 1
      const decision = await this.preStep(target, { turn, step })
      if (decision.kind === 'reject') {
        turnEnds = { kind: 'blocked' }
        return false
      }
      try {
        if (turnEnds && decision.messages.length === 0) break
        // A removed waking message or an enter decision rewritten to empty
        // still owns the initial turn boundary, but it spends no model call.
        if (phase.step === 0 && decision.messages.length === 0) {
          turnEnds = { kind: 'completed' }
          return false
        }
        signal.throwIfAborted()
        this.session.append('step/start', { turn, step })
        phase.step = step
        const toolRecovery = new ToolCallRecovery()
        const stopRecovery = this.ctx.on('session/event', (session, event) => {
          if (session === this.session) toolRecovery.observe(event)
        })
        try {
          // max-tokens is sticky: once any step hits the ceiling, later steps
          // that complete normally must not downgrade the turn outcome.
          const stepEnd = await this.step(decision)
          // max-tokens stays sticky: a later completed step must not
          // downgrade the turn outcome.
          if (turnEnds === null || turnEnds.kind !== 'max-tokens') turnEnds = stepEnd
        } catch (error: unknown) {
          try {
            for (const event of toolRecovery.results()) {
              this.session.append('tool/result', event.data, {
                surfaceOp: 'append',
                ...event.sourceEventSeqs === undefined ? {} : { sourceEventSeqs: event.sourceEventSeqs },
              })
            }
          } catch (recoveryError: unknown) {
            throw new AggregateError([error, recoveryError], 'Step failed and its pending tool results could not be recorded', { cause: error })
          }
          throw error
        } finally {
          stopRecovery()
          this.session.append('step/end', { turn, step })
        }
      } finally {
        // Admission closes once the step's tool batch settles or no step opens.
        decision.toolSet.dispose()
      }
      signal.throwIfAborted()
      if (turnEnds && this.inbox.nextStep.length === 0) {
        await this.dispatch.serial('agent/turn-stopping', { turn, signal })
        signal.throwIfAborted()
      }
      if (turnEnds && this.inbox.nextStep.length === 0) break
      target = 'next-step'
    }
  } catch (error: unknown) {
    // A cause is present exactly while the signal is aborted.
    const cause = abortedCancelCause(signal)
    if (cause !== undefined) {
      turnEnds = { kind: 'aborted', reason: cause }
      throw error
    }
    // Every failure is structured: an `LlmError` keeps its facts, a tool
    // activation failure keeps its code, and anything else flattens to
    // `errorChain` text under the `UNKNOWN` code.
    turnEnds = {
      kind: 'error',
      error: error instanceof LlmError
        ? error.failure
        : { message: errorChain(error), code: error instanceof ToolActivationError ? error.code : 'UNKNOWN' },
    }
    this.throwError(error)
  } finally {
    try {
      // oxlint-disable-next-line typescript/no-non-null-assertion -- every exit assigns a turn ending
      this.session.append('turn/end', { turn, reason: turnEnds! })
    } catch (error: unknown) {
      this.throwError(error)
    }
  }
  if (!this.inbox.hasPending) return false
  phase.abort = new AbortController()
  // A fresh controller makes a latch set on the old one stale: the live driver claims the queue itself.
  phase.wakeRequested = false
  phase.step = 0
  return true
}

private async step(decision: Extract<PreparedStep, { kind: 'enter' }>): Promise<StepEndReason | null> {
  /* v8 ignore next -- private callers establish the running phase before executing a step */
  if (this.phase.kind !== 'running') throw new Error(`agent "${this.id}": step outside running phase`)
  const { turn, step, abort: { signal } } = this.phase
  signal.throwIfAborted()

  const { assembly } = decision
  const renderedPrompt = renderPrompt(assembly)
  let firstAttempt = true
  while (true) {
    const { config, preparedCall } = await this.prepareRequest(turn, step, decision.selection, signal)
    const currentContext = this.loopCtx.systemPrompt.refreshContext(assembly, {
      ...assembleContextFor(this, signal), modelSelection: decision.selection,
    })
    const sections = renderContextSections(currentContext)
    const context = this.runtimeContext.project(joinContextSections(sections), sections)
    signal.throwIfAborted()
    const startsRequestSeries = firstAttempt && decision.startsRequestSeries === true
    const commits = this.systemPrompt.project(renderedPrompt, {
      inHistory: preparedCall?.systemPromptUpdate === 'in-history',
      startsSeries: startsRequestSeries
        || this.requestSurfaceGeneration !== this.session.surface.contentGeneration
        || (preparedCall?.toolUpdate === undefined && this.toolsChanged(assembly.tools)),
    })
    for (const { message, intent } of commits) {
      this.session.append('system/message', { turn, step, message }, intent)
    }
    let contextAdmitted = false
    if (firstAttempt) {
      for (const message of decision.messages) {
        if (message.source.kind === 'runtime-context') {
          if (context !== undefined && !contextAdmitted) {
            this.session.append('user/message', context, { surfaceOp: 'append' })
            contextAdmitted = true
          }
        } else {
          this.session.append('user/message', message, { surfaceOp: 'append' })
        }
      }
    }
    if (context !== undefined && !contextAdmitted) {
      this.session.append('user/message', context, { surfaceOp: 'append' })
    }
    firstAttempt = false
    const request = this.buildRequest(config, preparedCall, assembly.tools, { turn, step }, startsRequestSeries, signal)
    const live = new AssistantStreamAttempt(
      this.session.id,
      ++this.assistantAttemptCounter,
      () => ++this.assistantStreamRevision,
      turn,
      step,
      (frame) => { this.dispatch.emit('agent/assistant-stream', { frame }) },
    )
    let started = false
    try {
      const stream = preparedCall?.stream(request) ?? this.loopCtx.llm.stream(request)
      signal.throwIfAborted()
      live.start()
      started = true
      for await (const chunk of stream) {
        signal.throwIfAborted()
        live.push(chunk)
      }
      signal.throwIfAborted()
    } catch (error: unknown) {
      if (!started) throw error

  try {
    const finish = live.finish
    if (finish.kind === 'error' || finish.kind === 'aborted') {
      live.settle(
        'assistant/attempt',
        () => this.session.append('assistant/attempt', { turn, step, stream: live.stream }).seq,
      )
      const action = await this.dispatch.waterfall(
        'agent/request-error', {
          turn,
          step,
          provider: request.provider,
          failure: finish.failure,
          retryPolicy: preparedCall?.retryPolicy,
          signal,
        },
        () => Promise.resolve<RequestErrorAction>(undefined),
      )
      signal.throwIfAborted()
      if (action?.kind !== 'retry') {
        throw new LlmError(finish.failure.message, finish.failure.code, finish.failure)
      }
      continue
    }

    const message = createAssistantMessage({
      content: live.blocks(),
      source: {
        provider: request.provider,
        model: request.model,
        ...live.replayState !== undefined ? { replayState: live.replayState } : {},
      },
    })
    live.settle(
      'assistant/message',
      () => this.session.append('assistant/message', {
        turn,
        step,
        message,
        ...live.usage === undefined ? {} : { usage: live.usage },
        stream: live.stream,
      }, { surfaceOp: 'append' }).seq,
    )
    if (finish.kind === 'max-tokens') return { kind: 'max-tokens' }

    const toolCalls = message.content.filter(block => block.type === 'tool-call')
    if (toolCalls.length === 0) return { kind: 'completed' }
    const maxParallelToolCalls = this.loopCtx.agentLoop.config.maxParallelToolCalls.get()
    try {
      const result = await this.loopCtx.tools.execute({
        calls: toolCalls, signal, agent: this, log: { turn, step },
        maxParallelToolCalls, toolSet: decision.toolSet,
      })
      for (const context of result.additionalContexts) {
        this.inbox.splice('next-step', this.inbox.nextStep.length, 0, [context])
      }
      return result.concluded ? { kind: 'completed' } : null
    } catch (error: unknown) {
      if (!(error instanceof ToolBatchExecutionError)) throw error
      for (const context of error.partial.additionalContexts) {
        this.inbox.splice('next-step', this.inbox.nextStep.length, 0, [context])
      }
      throw error.cause
    }
  } catch (error: unknown) {
    if (!live.ended) live.abandon()
    throw error
  }
}

private async prepareRequest(
  turn: number,
  step: number,
  selection: Readonly<ModelSelection>,
  signal: AbortSignal,
): Promise<{ config: LlmCallConfig; preparedCall?: PreparedLlmCall }> {
  const { session } = this

  // A loop instance seeds output controls from its options until it logs its
  // own header; later steps re-resolve marked defaults.
  const maxTokens = this.options.maxTokens
  const persisted: Partial<LlmCallConfig> = this.requestHeaderLogged
    // oxlint-disable-next-line typescript/no-non-null-assertion -- the instance logged the header it now folds
    ? requestProposal(session.requestHeader()!)
    : maxTokens === undefined ? {} : { maxTokens }
  const { provider: _provider, model: _model, reasoningEffort: _effort, ...controls } = persisted
  const seedConfig = deepFreeze(structuredClone({ ...controls, ...selection }))
  const proposedConfig = await this.dispatch.waterfall(
    'agent/request', { turn, step, signal },
    () => Promise.resolve(seedConfig),
  )
  signal.throwIfAborted()
  if (proposedConfig.provider !== selection.provider || proposedConfig.model !== selection.model) {
    throw new Error(`agent "${this.id}": agent/request proposed "${proposedConfig.provider}/${proposedConfig.model}" after step preparation fixed "${selection.provider}/${selection.model}"; use agent.model.select() before step preparation`)
  }
  if (proposedConfig.reasoningEffort !== selection.reasoningEffort) {
    throw new Error(`agent "${this.id}": agent/request proposed reasoning effort "${proposedConfig.reasoningEffort ?? 'adapter default'}" after step preparation fixed "${selection.reasoningEffort ?? 'adapter default'}"; use agent.model.select() before step preparation`)
  }
  let config: LlmCallConfig
  let preparedCall: PreparedLlmCall | undefined
  try {
    preparedCall = await this.loopCtx.llm.prepareCall(proposedConfig, signal)
    config = preparedCall.config
  } catch (error: unknown) {
    // Middleware may serve an unregistered route; terminal dispatch still requires an adapter.
    if (!(error instanceof LlmError) || error.code !== 'NO_ADAPTER') throw error
    config = proposedConfig
  }
  signal.throwIfAborted()
  return { config, ...preparedCall === undefined ? {} : { preparedCall } }
}

private buildRequest(
  config: LlmCallConfig,
  preparedCall: PreparedLlmCall | undefined,
  tools: GenerateOptions['tools'] & object,
  position: { turn: number; step: number },
  startsRequestSeries: boolean,
  signal: AbortSignal,
): GenerateOptions {
  const { session } = this
  const surfaceGeneration = session.surface.contentGeneration
  const header = canonicalHeader({
    config,
    ...preparedCall === undefined ? {} : { adapterDefaults: preparedCall.adapterDefaults },
    ...tools.length > 0 ? { tools } : {},
  })
  const baseline = this.session.requestHeader()
  const startsSeries = startsRequestSeries
    || this.requestSurfaceGeneration !== surfaceGeneration
  let headerSeq: SessionSeq | undefined
  if (!this.requestHeaderLogged) {
    // Compaction during the first resumed pre-step must still mark a new series.
    headerSeq = this.session.append('request/header', {
      header,
      reason: baseline === undefined ? 'initial' : 'resume',
      ...startsSeries ? { startsSeries: true } : {},
    }).seq
    this.requestHeaderLogged = true
  } else if (baseline === undefined || !headerEquals(baseline, header)) {
    headerSeq = this.session.append('request/header', {
      header,
      reason: 'change',
      ...startsSeries ? { startsSeries: true } : {},
    }).seq
  } else if (startsSeries) {
    this.session.append('request/header', { header, reason: 'series' })
  }
  if (baseline !== undefined && headerSeq !== undefined) {
    const previousNames = new Set(baseline.tools?.map(tool => tool.name))
    const currentNames = new Set(tools.map(tool => tool.name))
    const additions = tools.filter(tool => !previousNames.has(tool.name))
      .map(tool => ({ type: 'tool-addition' as const, toolName: tool.name }))
    const removals = (baseline.tools ?? []).filter(tool => !currentNames.has(tool.name))
      .map(tool => ({ type: 'tool-removal' as const, toolName: tool.name }))
    if (additions.length > 0 || removals.length > 0) {
      session.append('developer/message', {
        ...position,
        message: createDeveloperMessage({ source: { kind: 'tool-registry' }, content: [...additions, ...removals] }),
        ...additions.length > 0 ? { headerSeq } : {},
      }, { surfaceOp: 'append' })
    }
  }
  this.requestSurfaceGeneration = surfaceGeneration

  const contextWindow = preparedCall?.context?.contextWindow

append<T extends SessionEventType>(
  type: T,
  data: SessionEventMap[T],
  ...opts: T extends SurfaceEventType ? [opts: SurfaceIntent<T>] : []
): SessionEvent<T> {
  this.publicationEntry()
  const surfaceOpts: SurfaceIntent | undefined = opts[0]
  const surfaceMetadata = {
    ...surfaceOpts?.sourceEventSeqs === undefined ? {} : { sourceEventSeqs: surfaceOpts.sourceEventSeqs },
    ...surfaceOpts?.surfaceOp === undefined ? {} : { surfaceOp: surfaceOpts.surfaceOp },
  }
  const dataSnapshot = snapshotJsonValue(data)
  if (dataSnapshot === undefined) {
    throw new Error(`session event "${type}" carries non-JSON-serializable data`)
  }
  const surfaceMetadataSnapshot = snapshotJsonValue(surfaceMetadata)
  if (surfaceMetadataSnapshot === undefined) {
    throw new Error(`session event "${type}" carries non-JSON-serializable surface metadata`)
  }
  // Payload getters can detach the Session while the snapshots are read.
  const entry = this.publicationEntry()
  const event = deepFreeze({
    type,
    seq: SessionSeq(this.log.length),
    time: Date.now(),
    data: dataSnapshot,
    ...(surfaceMetadataSnapshot as { surfaceOp?: unknown; sourceEventSeqs?: unknown }),
  } as unknown as SessionEvent<T>)
  validateSessionEventData(event, `session event "${type}" at seq ${event.seq}`)
  this.commit(event as SessionEvent, entry)
  return event
}

/**
 * Accept one frozen candidate at the next sequence number, enter it into the
 * log, and notify `session/event` observers with per-listener containment.
 * @param event - the candidate built at the current log length.
 * @param entry - the attachment read before the candidate was built.
 */
private commit(event: SessionEvent, entry: SessionEntry | undefined): void {
  this.surfaceManager.validateNext(event)

  if (entry !== undefined) entry.appending = true
  try {
    const callbackArgs: unknown[] = [this, event]
    const callbacks = entry === undefined
      ? undefined
      : collectSessionCallbacks(entry.emitCtx, [entry.carrier, 'session/event', ...callbackArgs])
    this.log.push(event)
    this.eventsSnapshot = undefined
    if (entry !== undefined && callbacks !== undefined) {
      invokeContainedSessionObservers(entry.emitCtx, 'session/event', entry.id, callbackArgs, callbacks)
    }
  } finally {
    if (entry !== undefined) {
      entry.appending = false
      if (entry.detachRequested && entry.announcement !== 'dispatching') entry.detach()
    }
  }
}

deriveMessages(): Message[] {
  const surface = this.surface
  const nodes = surface.nodes
  const generation = surface.contentGeneration
  if (generation !== this.derivedGeneration) {
    this.derived = []
    this.derivedNodes = 0
    this.derivedGeneration = generation
  }
  for (const seq of nodes.slice(this.derivedNodes)) {
    // Surface sequences are built from this.log — seq is always a valid
    // index by construction. The non-null assertion expresses that invariant.
    // oxlint-disable-next-line typescript/no-non-null-assertion
    const msg = this.deriveEventMessage(this.log[seq]!)
    // A surface node is one of the five message-producing types, but an
    // empty-content assistant/message (a max-tokens step that hosts only
    // usage) derives to null and must not enter the transcript.
    if (msg) this.derived.push(msg)
  }
  this.derivedNodes = nodes.length
  return [...this.derived]
}

/**
 * Delegate a raw call batch to its Agent's provider or the deployment default.
 * Select at dispatch; accepted batches settle through that provider even if it unloads.
 * @param input - original calls, optional owning Agent, and optional logging step.
 * @returns the selected executor's settled batch; unavailable selections reject.
 */
async execute(input: ToolBatchInput): Promise<ToolBatchResult> {
  return this.selectExecutor(input.agent).execute(input)
}

/**
 * Snapshot input, assign its correlation token, and run ordered pre-execute
 * policy and guards. Cancellation skips a body that has not started.
 * @param input - the caller-supplied execution input.
 * @returns the prepared execution plus the next scheduler stage.
 */
async prepare(input: ToolExecutionInput): Promise<ScheduledToolPreparation> {
  const created = this.createExecution(input)
  if (created.kind !== 'ready') return created
  const exec = created.exec
  if (this.callerCancelled(exec)) {
    return { kind: 'final-result', exec, result: toolAbortedBeforeDispatchResult() }
  }
  try {
    const carrier = scopeTarget(this.tools, exec.agent)
    const gate = await this.ctx.waterfall(
      carrier, 'tools/pre-execute', exec,
      () => Promise.resolve<PreToolDecision>({ kind: 'allow' }),
    )
    const askResolution = gate.kind === 'ask'
      ? await this.serviceAsk(exec, gate)
      : { decision: gate, approvalCancelled: false }
    const { decision } = askResolution
    if (this.callerCancelled(exec) && askResolution.approvalCancelled) {
      return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }
    }
    if (decision.kind === 'cancel') {
      return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }
    }
    const denialReason = decision.kind === 'allow' ? this.tools.checkGuards(exec) : decision.reason
    const denialInfo = decision.kind === 'deny' ? decision.info : undefined
    if (denialReason !== undefined) {
      return {
        kind: 'post-result',
        exec,
        result: this.materializeFinalResult({
          content: [{ type: 'text', text: `Error: ${denialReason}` }],
          isError: true,
          error: { message: denialReason, ...denialInfo === undefined ? {} : { info: denialInfo } },
        }),
      }
    }
    if (this.callerCancelled(exec)) {
      return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }
    }
    return { kind: 'dispatch', exec }
  } catch (error: unknown) {
    return { kind: 'final-result', exec, result: toolErrorResult(error) }
  }
}

/**
 * Run around-dispatch and the tool body. Tool and unknown-tool failures still
 * receive post-execute; pipeline failures are already final. Started bodies
 * drain on cancellation before a successful outcome becomes `ABORTED`.
 * @param exec - the execution returned by this pipeline's prepare stage.
 * @returns whether the result still needs post-execute.
 */
async dispatch(exec: ToolRunContext): Promise<ScheduledToolDispatch> {
  try {
    const mutableExec = exec as MutableToolRunContext
    const carrier = scopeTarget(this.tools, exec.agent)
    const result = await this.ctx.waterfall(
      carrier, 'tools/execute', mutableExec,
      () => this.dispatchToolBody(mutableExec),
    )
    const normalized = this.normalizeDispatchResult(exec, result)
    const deferredContexts = this.deferredContexts.get(exec)
    /* v8 ignore next -- dispatch only receives executions minted by this registry's prepare stage */
    if (deferredContexts === undefined) throw new Error('tool registry scheduler invariant violated: unprepared execution')
    const resultWithDeferredContexts: ToolExecutionResult = deferredContexts.length === 0
      ? normalized
      : this.markCanonical(exec, {
        ...normalized,
        additionalContexts: [
          ...deferredContexts,
          ...normalized.additionalContexts ?? [],
        ],
      })
    return {
      kind: 'post-result',
      result: this.callerCancelled(exec) && !resultWithDeferredContexts.isError
        ? this.cancellationResult(exec, resultWithDeferredContexts)
        : resultWithDeferredContexts,
    }
  } catch (error: unknown) {
    return { kind: 'final-result', result: toolErrorResult(error) }
  }
}

/**
 * Run the `tools/post-execute` waterfall over a dispatched `result` and apply
 * its {@link PostToolDecision}: `accept` keeps the call successful (replacing
 * `content` when given), `block` turns it into an `isError` whose content is
 * the corrective `feedback`. Either decision may attach `additionalContexts`,
 * which are ferried on the returned result for the loop's active-batch FIFO.
 * Context deferred by the tool body survives an accepted result but is
 * discarded when the outer call is blocked; a block exposes only context the
 * blocking decision explicitly supplied.
 * Runs inside `execute`'s outer try/catch (a throwing listener → isError).
 */
private async postExecute(exec: ToolExecution, result: ToolExecutionResult): Promise<ToolExecutionResult> {
  const decision = await this.ctx.waterfall(
    scopeTarget(this.tools, exec.agent), 'tools/post-execute', exec, result,
    () => Promise.resolve<PostToolDecision>({ kind: 'accept' }),
  )
  const decisionContexts = decision.additionalContexts ?? []
  if (decision.kind === 'block') {
    const message = failureMessageFromContent(decision.feedback)
    return this.markCanonical(exec, {
      content: decision.feedback,
      isError: true,
      error: { message },
      ...decisionContexts.length > 0 ? { additionalContexts: decisionContexts } : {},
    })
  }
  if (Object.hasOwn(decision, 'content') && Object.hasOwn(decision, 'value')) {
    throw new TypeError('tools/post-execute accept decision cannot replace both value and content')
  }
  const additionalContexts = [
    ...result.additionalContexts ?? [],
    ...decisionContexts,
  ]
  if (Object.hasOwn(decision, 'value')) {
    if (result.isError) {
      throw new TypeError('tools/post-execute cannot replace the value of a failed result')
    }
    const tool = this.resolveExecution(exec.name, exec.agent, exec.parent !== undefined, exec.toolSet)
    if (tool === undefined) throw new ToolNotFoundError(exec.name)
    const replaced = this.createSuccessResult(exec, tool, decision.value)
    return this.markCanonical(exec, {
      ...replaced,
      ...additionalContexts.length > 0 ? { additionalContexts } : {},
    })
  }
  return this.markCanonical(exec, {
    ...result,
    ...decision.content !== undefined ? { content: decision.content } : {},
    ...additionalContexts.length > 0 ? { additionalContexts } : {},
  })

async prepareCall(
  config: LlmCallConfig,
  signal?: AbortSignal,
  configure?: ConfigureCall,
): Promise<PreparedLlmCall> {
  signal?.throwIfAborted()
  const { provider, model, ...controls } = config
  const registration = this.registration(provider)
  const adapterCall = await registration.adapter.prepareCall(provider, model, signal)
  signal?.throwIfAborted()
  const modelInfo = this.normalizeModelInfo(registration, model, adapterCall.model)
  const proposed = configure === undefined
    ? config
    : { ...configure(deepFreeze(structuredClone(controls)), deepFreeze(modelInfo)), provider, model }
  signal?.throwIfAborted()
  const resolved = this.resolveCallWithInfo(proposed, modelInfo)
  const resolvedConfig = deepFreeze(structuredClone(resolved.config))
  const context = resolved.context === undefined
    ? undefined
    : deepFreeze(structuredClone(resolved.context))
  const adapterDefaults = deepFreeze<LlmCallConfigAdapterDefaults>({
    ...proposed.reasoningEffort === undefined && resolvedConfig.reasoningEffort !== undefined
      ? { reasoningEffort: true }
      : {},
    ...proposed.maxTokens === undefined && resolvedConfig.maxTokens !== undefined
      ? { maxTokens: true }
      : {},
  })
  let dispatched = false
  return Object.freeze({
    config: resolvedConfig,
    retryPolicy: registration.retryPolicy,
    adapterDefaults,
    ...context === undefined ? {} : { context },
    ...modelInfo.inputModalities === undefined
      ? {}
      : { inputModalities: Object.freeze([...modelInfo.inputModalities]) },
    ...modelInfo.systemPromptUpdate === undefined ? {} : { systemPromptUpdate: modelInfo.systemPromptUpdate },
    ...modelInfo.toolUpdate === undefined ? {} : { toolUpdate: modelInfo.toolUpdate },
    stream: (options: GenerateOptions): AsyncIterable<StreamChunk> => {
      if (dispatched) {
        throw new LlmError('a prepared LLM call can only be dispatched once', 'INVALID_PREPARED_CALL')
      }
      if (!callConfigEquals(options, resolvedConfig)) {
        throw new LlmError(
          'prepared LLM call config changed before adapter dispatch',
          'INVALID_PREPARED_CALL',
        )
      }
      dispatched = true
      return this.streamWithRegistration(options, {
        registration,
        config: resolvedConfig,
        modelInfo,
        dispatch: options => adapterCall.stream(options),
      })
    },
  })
}

/**
 * Stream one model call as raw chunks (token-level deltas). Replay state is
 * retained only when the same adapter instance owns its historical provider
 * and the target provider. Final adapter selection remains fixed through
 * asynchronous exact-model resolution and dispatch. Adapter selection,
 * dispatch, and iteration failures become terminal `error` or `aborted`
 * finish chunks; middleware, nested-call, cleanup, and consumer failures
 * remain thrown.
 * @param options - the full request; `options.provider` selects the adapter.
 * @returns the chunk stream, possibly wrapped by `llm/stream` listeners.
 */
stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
  return this.streamWithRegistration(options)
}

private streamWithRegistration(
  options: GenerateOptions,
  prepared?: PreparedDispatch,
): AsyncIterable<StreamChunk> {
  return this.ctx.waterfall(
    this,
    'llm/stream',
    options,
    () => this.adapterStream(options, prepared),
  )
}

/**
 * Raw streaming protocol emitted by adapters.
 * Block indexes correlate interleaved deltas, and `block-end` carries the
 * assembled block. Adapters emit usage before the terminal finish and nothing
 * afterward; tool arguments remain raw JSON strings. An adapter implementation
 * may throw, but `LlmRuntime.stream()` normalizes that failure to a terminal
 * `error` or `aborted` finish before exposing it to consumers.
 */
export type StreamChunk =
  | { type: 'block-start'; index: number; blockType: ContentBlockType }
  | { type: 'text-delta'; index: number; text: string }
  | { type: 'reasoning-delta'; index: number; text: string }
  | { type: 'tool-call-delta'; index: number; id: ToolCallId; name?: string; argumentsDelta: string }
  | { type: 'block-end'; index: number; block: ContentBlock }
  | { type: 'usage'; usage: TokenUsage }
  | {
    type: 'finish'
    reason: FinishReason
    /** Replay metadata for a successful response; see {@link ReplayEnvelope}. */
    replayState?: ReplayEnvelope
  }

/**
 * Assemble global and scoped providers, detach tool parameters, apply
 * canonical ordering, then run the presentation waterfall. Scoped sections
 * and variables shadow globals. The waterfall's text is authoritative except
 * that an effective complete section is restored afterwards as the sole
 * prompt section; tool declarations stay provider-owned.
 * @param context - the optional scope, step tool set, and plugin-defined assembly fields.
 * @returns the post-waterfall assembly with ordered tool declarations and any complete prompt enforced.
 */
// Keep configuration failures on the declared asynchronous error path.
async assemble(context: AssembleContext = {}): Promise<PromptAssembly> {
  const scope = context.scope
  const scopeLayers = this.layers.chainLayers(scope)
  const runtimeContextSuppressed = !this.layers.global.runtimeContextSuppressors.isEmpty()
    || scopeLayers.some(layer => !layer.runtimeContextSuppressors.isEmpty())
  // Scoped variables shadow globals.
  const variables: Record<string, string | undefined> = {}
  for (const [name, provider] of this.layers.global.variables.entries()) {
    variables[name] = provider(context)
  }
  // Scope-chain variables, farthest first, so the nearest scope wins a name.
  for (const layer of scopeLayers) {
    for (const [name, provider] of layer.variables.entries()) {
      variables[name] = provider(context)
    }
  }
  // Scoped sections shadow globals before the deterministic order sort.
  const sectionByName = this.layers.merge(scope, layer => layer.sections)
  const contextByName = this.layers.merge(scope, layer => layer.contexts)
  // Validate order against pre-restriction names while collecting visible schemas.
  const providers = [
    ...this.layers.global.toolProviders.values(),
    ...scopeLayers.flatMap(layer => [...layer.toolProviders.values()]),
  ]
  const collected: ToolSchema[] = []
  const knownNames = new Set<string>()
  for (const provider of providers) {
    const result = provider(context)
    const schemas = result.schemas.map(({ name, description, parameters, deferLoading }): ToolSchema => ({
      name,
      description,
      parameters: structuredClone(parameters),
      ...deferLoading === true ? { deferLoading } : {},
    }))
    const acceptedKnownNames = result.knownNames ?? schemas.map(tool => tool.name)
    collected.push(...schemas)
    for (const name of acceptedKnownNames) knownNames.add(name)
  }
  const sectionDefinitions = [...sectionByName.values()].sort(comparePromptSections)
  const completeSections = sectionDefinitions.filter(section => section.complete === true)
  if (completeSections.length > 1) {
    throw new Error(`multiple complete prompt sections are active: ${completeSections.map(section => JSON.stringify(section.name)).join(', ')}`)
  }
  let completeSection: AssembledSection | undefined
  const sections = sectionDefinitions
    .map((section) => {
      const assembled = {
        name: section.name,
        text: typeof section.text === 'function' ? section.text(context) : section.text,
        ...section.interpolate !== undefined ? { interpolate: section.interpolate } : {},
      }
      if (section.complete === true) completeSection = { ...assembled }
      return assembled
    })
  const tools = orderTools(collected, this.toolOrder, knownNames)
  const assembly: PromptPresentation = {
    sections,
    contexts: [...contextByName.values()]
      .filter(entry => !runtimeContextSuppressed || entry.required === true)
      .sort((a, b) => a.order - b.order)
      .map(entry => resolveContext(entry, context)),
    variables,
  }
  const transformed = await this.ctx.waterfall(
    scopeTarget(this, scope), 'system-prompt/assemble', assembly, context,
    () => Promise.resolve(assembly),
  )
  if (completeSection === undefined && !runtimeContextSuppressed) return { ...transformed, tools }
  const requiredContexts = new Set([...contextByName.values()].filter(entry => entry.required === true).map(entry => entry.name))
  return {
    ...transformed,
    tools,
    sections: completeSection === undefined ? transformed.sections : [completeSection],
    contexts: runtimeContextSuppressed ? transformed.contexts.filter(entry => requiredContexts.has(entry.name)) : transformed.contexts,
  }

/**
 * Admit one prompt after explicitly resuming its Session.
 * @param request - Session identity, prompt content, source metadata, and delivery mode.
 * @param signal - caller cancellation before prompt admission begins.
 * @returns acknowledgement that the Agent accepted the prompt.
 */
@Remote('prompt')
async prompt(request: SessionPromptRequest, signal: AbortSignal): Promise<SessionPromptValue> {
  signal.throwIfAborted()
  if (request.content.length > 0 && !hasPromptContent(request.content)) {
    throw new RemoteError('gateway/bad-request', 'prompt content must include non-whitespace text or an attachment', {})
  }
  const clientTimeZone = request.clientTimeZone === undefined
    ? undefined
    : canonicalClientTimeZone(request.clientTimeZone)
  if (request.clientTimeZone !== undefined && clientTimeZone === undefined) {
    throw new RemoteError(
      'session/invalid-time-zone',
      'clientTimeZone must be UTC or a valid IANA Area/Location name',
      { value: request.clientTimeZone },
    )
  }
  // The caller is recorded only when it is not the owner, so owner messages keep their exact source.
  const principal = principalOf(this.ctx.invocation)
  const source: MessageSource = {
    kind: request.content.length === 0 ? 'retry' : 'user',
    rpcId: request.requestId,
    ...(clientTimeZone === undefined ? {} : { clientTimeZone }),
    ...(principal === undefined ? {} : { principal }),
  }
  return this.commands.prompt(request, source)
}

async prompt(request: SessionPromptRequest, source: MessageSource): Promise<SessionPromptValue> {
  const agent = await this.resolveAgent(request.sessionId)
  if (this.hasPromptRequest(agent.session, request.requestId)) return { accepted: true }
  if (request.content.length === 0) {
    try {
      return await agent.runMaintenance(() => {
        const inbox = agent.inbox
        if (request.mode !== 'queue' || this.continuation.stateOf(agent.session).ending === null
          || inbox.nextTurn.length > 0 || inbox.nextStep.some(message => message.source.kind === 'user')) {
          throw new RemoteError('session/agent-busy', 'generation continuation is unavailable', { reason: 'NO_CONTINUABLE_FAILURE_OR_PENDING_INPUT' })
        }
        agent.followup(createUserMessage({ content: [], source }))
        return Promise.resolve({ accepted: true as const })
      })
    } catch (error: unknown) {
      if (remoteErrorOf(error) !== undefined) throw error
      throw new RemoteError('session/agent-busy', 'generation continuation was not accepted', { reason: String(error) })
    }
  }
  const admission = resolvePromptFileReceipts(
    request.content,
    receiptId => this.ctx.fileUploads.resolve(agent, receiptId),
  )
  // Encoded images and image upload receipts both make an image prompt.
  const hasImage = admission.content.some(part => part.type === 'image')
  const admit = async (): Promise<SessionPromptValue> => {
    try {
      if (this.hasPromptRequest(agent.session, request.requestId)) return { accepted: true }
      if (hasImage) {
        const current = agent.model.current()
        if (current !== undefined) {
          const model = await this.ctx.llm.resolveModelInfo(current.provider, current.model)
          if (model.inputModalities !== undefined && !model.inputModalities.includes('image')) {
            throw new RemoteError(
              'session/attachment-invalid',
              `Model "${current.model}" does not support image input.`,
              { reason: 'MODEL_DOES_NOT_SUPPORT_IMAGES' },
            )
          }
        }
      }
      const content = await this.ctx.attachments.admitPromptContent(admission.content)
      if (this.hasPromptRequest(agent.session, request.requestId)) return { accepted: true }
      const message: UserMessage = createUserMessage({ content, source })
      if (this.ctx.agents.get(agent.id) !== agent) {
        throw new RemoteError(
          'session/not-found',
          `session "${agent.id}" was disposed during prompt admission`,
          { sessionId: agent.id },
        )
      }
      using binding = this.ctx.fileUploads.bindPrompt(agent, admission.receiptIds, request.requestId)
      if (request.mode === 'steer') agent.steer(message)
      else agent.followup(message)
      binding.commit()
    } catch (error) {
      if (this.hasPromptRequest(agent.session, request.requestId)) return { accepted: true }
      if (remoteErrorOf(error) !== undefined) throw error
      if (error instanceof AttachmentError) {
        throw new RemoteError('session/attachment-invalid', error.message, { reason: error.code })
      }
      throw new RemoteError('session/agent-busy', 'prompt rejected', { reason: String(error) })
    }
    return { accepted: true }
  }
  return hasImage ? this.agents.serializeImageAdmission(agent, admit) : admit()
}

/**
 * Send (queue/steer passed through 1:1); failures land in the snapshot's
 * promptError. The Host can hold the prompt at its admission stage, so the
 * call can stay open; the echo appears and the blank → engaging edge flips
 * only once the Host accepts the prompt.
 * @param content - text, browser-owned temporary image uploads, and staged-file receipts.
 * @param mode - queue appends after the current turn; steer interrupts it.
 * @param signal - optional caller cancellation for the complete admission round-trip.
 * @param requestId - identity from {@link beginSubmission}; a failed identified prompt retires its echo.
 * @returns the prompt result (also mirrored into promptError on failure).
 */
async prompt(
  content: PromptContentPart[],
  mode: 'queue' | 'steer',
  signal?: AbortSignal,
  requestId?: SessionRequestId,
): Promise<RemoteResult<{ accepted: true }>> {
  this.promptError = null
  this.lastAgentError = null
  // Before the first await, so a turn observed ahead of the receipt clears it.
  const firstPrompt = this.blankBit && !this.firstPromptPendingTurn
  if (firstPrompt) this.firstPromptPendingTurn = true
  let result: RemoteResult<{ accepted: true }>
  if (this.address === undefined) {
    const clientTimeZone = resolvedClientTimeZone()
    result = await this.remote.session.prompt({
      requestId: requestId ?? randomUUID() as SessionRequestId,
      sessionId: this.sessionId,
      mode,
      content,
      clientTimeZone,
    }, signal)
  } else if (content.some(part => part.type === 'file')) {
    result = {
      ok: false,
      error: new RemoteError(
        'subagent/attachment-invalid',
        'subagent continuation does not accept files',
        { reason: 'SUBAGENT_FILE_UNSUPPORTED' },
      ),
    }
  } else {
    // The preceding branch rejects file parts before the narrower subagent
    // wire type is used; this array is not filtered or reordered.
    const routedContent = content as Exclude<PromptContentPart, { readonly type: 'file' }>[]
    const routed = await this.remote.subagents.prompt({
      requestId: requestId ?? randomUUID() as SessionRequestId,
      childSessionId: this.address.childSessionId,
      delivery: mode,
      content: routedContent,
      clientTimeZone: resolvedClientTimeZone(),
    }, signal)
    result = routed.ok ? { ok: true, value: { accepted: true } } : routed
  }

/**
 * Send a prompt into the scoped session. Business failures also land in the
 * session snapshot's promptError (object-layer state); the rejection here
 * exists for caller choreography (the composer restores the draft on it).
 * @param text - prompt text, sent verbatim as one text block.
 */
async send(text: string): Promise<void> {
  const session = this.scopedSession('send')
  const result = await session.prompt([{ type: 'text', text }], 'queue')
  if (!result.ok) throw new Error(`conversation.send failed: ${result.error.code}: ${result.error.message}`)
}

